exploreUrl:
@js:(function(){
    let discovery = []
    let doc = org.jsoup.Jsoup.parse(java.ajax(baseUrl))
    let items = doc.select(".navigation>ul a")

    function generateDiscoveryFromSecondary(pageSource){
        let page =org.jsoup.Jsoup.parse(pageSource)
        let items = page.select(".container .row a")
        if (items.length == 0){
            return []
        }
        let result = []
        for(let i = 0; i < items.length; i++){
            let e = items[i]
            let href = e.attr('href')
            // 可翻页
            if(href.match(/\/\d+$/)){
                href += '/{{page}}'
            }
            result.push({
                title: e.text(),
                url: href,
                style: {
                    layout_wrapBefore: i == 0
                }
            })
        }
        return result
    }
    function isSecondaryList(pageSource){
        return generateDiscoveryFromSecondary(pageSource).length != 0
    }
    for(let key in items){
        let href = baseUrl + items[key].attr("href")
        let pageSource = java.ajax(href)
        let secondary = isSecondaryList(pageSource)
        // 可翻页
        if(href.match(/\/\d+$/)){
            href += '/{{page}}'
        }
        discovery.push({
            title: items[key].text(),
            style: {
                layout_flexGrow: 1,
                layout_alignSelf: "stretch",
                layout_flexShrink: 0,
                layout_wrapBefore: true,
            },
            url: isSecondaryList(pageSource) ? undefined : href
        })
        if(secondary){
            for(let e of generateDiscoveryFromSecondary(pageSource)){
                discovery.push(e)
            }
        }

    }
    return JSON.stringify(discovery)
})()
